`,bl=`// New library script — shared, STATELESS helpers imported by other scripts.
// The import specifier is this file's EXACT name. If this file is
// collision.js, another script imports it as:
//
//   import { aabbOverlap, clamp } from 'zed:collision.js';
//
// Export pure functions / classes / constants only. Do NOT keep module-level
// mutable state — each importing node gets its own copy of this module, so a
// module-level accumulator is per-node, not shared. Put shared state in the
// importer's ctx.store, signals, data channels, or @output textures.
//
// (Annotations like // @param here are ignored — a library is never a node.)

/** Axis-aligned box overlap test. ax/ay/aw/ah and bx/by/bw/bh are corner+size. */
export function aabbOverlap(ax, ay, aw, ah, bx, by, bw, bh) {
  return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;
}

/** Clamp a value into [lo, hi]. */
export function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}
`,xl=`// New data-script node.
//
// A data-script writes std140 uniform blocks per frame instead of a
// texture. Each \`// @uniform-block <Name> { ... }\` block must be
// matched by a \`layout(std140) uniform <Name> { ... }\` declaration in
// the consuming shader (same name, same fields, same order).
//
// Wire the purple ports: this node's UBO output → a consumer shader's
// UBO input; an upstream analyser's AnalyserData UBO output → this
// node's analyser input below.

// @input audio analyser
// @uniform-block AudioDecoration {
//   vec4  envelope;   // [rms, rms*0.5, 0, 0]
//   float energy;     // current RMS
//   int   beatCount;  // rising-edge beats since reset
// }

let beats = 0;

export function initialise(ctx) {
  ctx.store.prevBeat = false;
  beats = 0;
}

export function render(ctx, inputs, outputs, time, timeDelta) {
  const a = inputs.audio;
  if (!a) return; // No upstream analyser wired yet — nothing to read.
  const f = a.frame();
  if (!f) return;
  if (f.beat.beat && !ctx.store.prevBeat) beats++;
  ctx.store.prevBeat = f.beat.beat;
  outputs.AudioDecoration.envelope.view.set([f.rms, f.rms * 0.5, 0, 0]);
  outputs.AudioDecoration.energy.set(f.rms);
  outputs.AudioDecoration.beatCount.set(beats);
}

export function destroy(ctx) {}
